INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1815255, 249462, 43565, '<td valign="top">I am not sure what is in the shirt, but it is overexposed.  If I saw this photo, I would not think light on white as there are too many dark areas.</td>', 'I am not sure what is in the shirt, but it is overexposed.  If I saw this photo, I would not think light on white as there are too many dark areas.', '2005-10-26 16:04:28.000000', NULL, 1),
