(1815257, 247113, 43148, '<td valign="top">sorry, see no light color on white background</td>', 'sorry, see no light color on white background', '2005-10-26 16:05:37.000000', NULL, 1),
(1815260, 249393, 43565, '<td valign="top">I think this would have been better in color so that the color of the eyes would show.</td>', 'I think this would have been better in color so that the color of the eyes would show.', '2005-10-26 16:07:45.000000', NULL, 1),
(1815262, 249593, 42638, '<td valign="top">Interesting picture. I like the way the light reflections dance towards the top there. Nice abstract.</td>', 'Interesting picture. I like the way the light reflections dance towards the top there. Nice abstract.', '2005-10-26 16:08:06.000000', NULL, 1),
