(1815273, 249266, 42638, '<td valign="top">Wow, Nice picture but It doesn''t really fit the challenge well. Like the colors, very strong.</td>', 'Wow, Nice picture but It doesn''t really fit the challenge well. Like the colors, very strong.', '2005-10-26 16:11:06.000000', NULL, 1),
(1815276, 246959, 42638, '<td valign="top">Nice picture but a bit blown. I really like the positioning of the flower, makes for a strong theme.</td>', 'Nice picture but a bit blown. I really like the positioning of the flower, makes for a strong theme.', '2005-10-26 16:12:12.000000', NULL, 1),
(1815278, 248980, 42638, '<td valign="top">Nice reflection. Interesting interpretation.</td>', 'Nice reflection. Interesting interpretation.', '2005-10-26 16:12:52.000000', NULL, 1),
