(1815387, 246699, 17507, '<td valign="top">the framing is interesting, and your white are nice and bright... but this just isn''t *light* on white.</td>', 'the framing is interesting, and your white are nice and bright... but this just isn''t *light* on white.', '2005-10-26 16:37:47.000000', NULL, 1),
(1815389, 249576, 43753, '<td valign="top">This is a very sharp macro, but not very interesting. It would have held more interest had it been further away. I don''t like that hot spot reflection on the neck of the bottle. 6</td>', 'This is a very sharp macro, but not very interesting. It would have held more interest had it been further away. I don''t like that hot spot reflection on the neck of the bottle. 6', '2005-10-26 16:38:04.000000', NULL, 1),
(1815391, 247590, 17507, '<td valign="top">great use of perspective to add visual interest. the pencil''s tip is a bit too dark for me to feel like this is really "light on white."</td>', 'great use of perspective to add visual interest. the pencil''s tip is a bit too dark for me to feel like this is really "light on white."', '2005-10-26 16:38:29.000000', NULL, 1),
(1815393, 249145, 17507, '<td valign="top">doesn''t meet the challenge :(</td>', 'doesn''t meet the challenge :(', '2005-10-26 16:39:19.000000', NULL, 1),
