(1815396, 249547, 17507, '<td valign="top">very interesting and effective setup!</td>', 'very interesting and effective setup!', '2005-10-26 16:39:43.000000', NULL, 1),
(1815400, 249261, 43565, '<td valign="top">I like the detail in the light, this does not seem to be "light on white".</td>', 'I like the detail in the light, this does not seem to be "light on white".', '2005-10-26 16:40:23.000000', NULL, 1),
(1815401, 247033, 43753, '<td valign="top">Very pretty. I like the shutterspeed. The only thing that bothers me is the clipped wing at the top. 7</td>', 'Very pretty. I like the shutterspeed. The only thing that bothers me is the clipped wing at the top. 7', '2005-10-26 16:40:26.000000', NULL, 1),
(1815404, 249410, 17507, '<td valign="top">I think the negative space should be on the side that the fan faces...</td>', 'I think the negative space should be on the side that the fan faces...', '2005-10-26 16:40:56.000000', NULL, 1),
(1815406, 248563, 43565, '<td valign="top">A little overexposed and I find the green in the background distracting.</td>', 'A little overexposed and I find the green in the background distracting.', '2005-10-26 16:41:02.000000', NULL, 1),
(1815408, 249418, 43753, '<td valign="top">This is a beautiful image, but the black speck on the rose is very distracting to me. I like the dappled look on the background. 7</td>', 'This is a beautiful image, but the black speck on the rose is very distracting to me. I like the dappled look on the background. 7', '2005-10-26 16:41:27.000000', NULL, 1),
(1815409, 248438, 43565, '<td valign="top">I like the eye color but I wish the white did not have such a blue tint.</td>', 'I like the eye color but I wish the white did not have such a blue tint.', '2005-10-26 16:41:39.000000', NULL, 1),
(1815411, 249336, 17507, '<td valign="top">great lines and textures. I like the gradation in the background - it adds a subtlety that wouldn''t be there if it were pure white. And the title is good as well :)</td>', 'great lines and textures. I like the gradation in the background - it adds a subtlety that wouldn''t be there if it were pure white. And the title is good as well :)', '2005-10-26 16:41:54.000000', NULL, 1),
(1815413, 248994, 43753, '<td valign="top">How novel. You kept the leaves looking soft even though they are no doubt a vibrant yellow. I love the composition. Very clean and simple. 8</td>', 'How novel. You kept the leaves looking soft even though they are no doubt a vibrant yellow. I love the composition. Very clean and simple. 8', '2005-10-26 16:42:11.000000', NULL, 1),
(1815416, 249590, 17507, '<td valign="top">a cool picture, but totally doesn''t meet the challenge! did you perhaps mean to submit this to Delicate?</td>', 'a cool picture, but totally doesn''t meet the challenge! did you perhaps mean to submit this to Delicate?', '2005-10-26 16:42:31.000000', NULL, 1),
(1815417, 249029, 43565, '<td valign="top">This does not have enough of a subject or focus for me, and the whole image appears yellowish-at least on my monitor.</td>', 'This does not have enough of a subject or focus for me, and the whole image appears yellowish-at least on my monitor.', '2005-10-26 16:42:31.000000', NULL, 1),
