(1817799, 249469, 43148, '<td valign="top">way too much darkness for a "white background" IMO</td>', 'way too much darkness for a "white background" IMO', '2005-10-27 12:30:53.000000', NULL, 1),
(1817806, 249332, 43148, '<td valign="top">love the dog, too much darkness on "white" background in upper left corner,  directly behind the middle of the dogs head and on right side, also IMO the color of the dog is not a "light" color, but I love the look and the capture so will give it a mid range anyway</td>', 'love the dog, too much darkness on "white" background in upper left corner,  directly behind the middle of the dogs head and on right side, also IMO the color of the dog is not a "light" color, but I love the look and the capture so will give it a mid range anyway', '2005-10-27 12:33:21.000000', NULL, 1),
(1817809, 248887, 40295, '<td valign="top">A bit too much light on parts of her face - looks just a tad overexposed. It might have worked better to go with less exposure and bring out the whites with curves in the post processing.</td>', 'A bit too much light on parts of her face - looks just a tad overexposed. It might have worked better to go with less exposure and bring out the whites with curves in the post processing.', '2005-10-27 12:33:46.000000', NULL, 1),
(1817810, 247488, 43148, '<td valign="top">feather is oof IMO</td>', 'feather is oof IMO', '2005-10-27 12:33:47.000000', NULL, 1),
(1817814, 247816, 40295, '<td valign="top">The post running up the middle of the image does not work for me.</td>', 'The post running up the middle of the image does not work for me.', '2005-10-27 12:34:34.000000', NULL, 1),
(1817818, 247922, 43148, '<td valign="top">lost definition on the mask in both the nose and mouth area, wish the dark lines were not there</td>', 'lost definition on the mask in both the nose and mouth area, wish the dark lines were not there', '2005-10-27 12:35:58.000000', NULL, 1),
(1817824, 249548, 43148, '<td valign="top">that be white on light, not light on white IMO</td>', 'that be white on light, not light on white IMO', '2005-10-27 12:36:39.000000', NULL, 1),
(1817825, 248219, 40295, '<td valign="top">good image - I would move the glass/bird a dad to the right to get it out of the middle of the image.  That would balance better with the bird looking to the left.</td>', 'good image - I would move the glass/bird a dad to the right to get it out of the middle of the image.  That would balance better with the bird looking to the left.', '2005-10-27 12:37:24.000000', NULL, 1),
(1817827, 249498, 43148, '<td valign="top">background shows too dark, otherwise nicely done</td>', 'background shows too dark, otherwise nicely done', '2005-10-27 12:38:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1817829, 248766, 43148, '<td valign="top">feather shows a little oof on left side, nice otherwise</td>', 'feather shows a little oof on left side, nice otherwise', '2005-10-27 12:38:49.000000', NULL, 1),
(1817830, 249417, 39665, '<td valign="top">Too cute!</td>', 'Too cute!', '2005-10-27 12:38:58.000000', NULL, 1),
(1817831, 248438, 40295, '<td valign="top">I would like just a little more contrast between the cat and the backgroud you have. As it is now the edges of the cat get lost in the background and I find that a bit disconcerting - just does not feel right.</td>', 'I would like just a little more contrast between the cat and the backgroud you have. As it is now the edges of the cat get lost in the background and I find that a bit disconcerting - just does not feel right.', '2005-10-27 12:39:18.000000', NULL, 1),
(1817832, 249618, 43148, '<td valign="top">think the duck is not well, looks a little "flushed" to me (sorry about that) LOL</td>', 'think the duck is not well, looks a little "flushed" to me (sorry about that) LOL', '2005-10-27 12:39:53.000000', NULL, 1),
(1817836, 247077, 40295, '<td valign="top">Need a little better crop at the top - to get rid of the dark area in the upper left.</td>', 'Need a little better crop at the top - to get rid of the dark area in the upper left.', '2005-10-27 12:40:56.000000', NULL, 1),
(1817838, 249610, 43148, '<td valign="top">colors are too blown out IMO</td>', 'colors are too blown out IMO', '2005-10-27 12:42:51.000000', NULL, 1),
(1817906, 248754, 23962, '<td valign="top">Great tones but why is everything shoved over to the left like that?</td>', 'Great tones but why is everything shoved over to the left like that?', '2005-10-27 13:15:14.000000', NULL, 1),
(1817910, 248997, 23962, '<td valign="top">Excellent capture.</td>', 'Excellent capture.', '2005-10-27 13:16:59.000000', NULL, 1),
(1817914, 246953, 23962, '<td valign="top">Dynamic and unreal. Croped a little tight. Great entry.</td>', 'Dynamic and unreal. Croped a little tight. Great entry.', '2005-10-27 13:18:57.000000', NULL, 1),
(1817916, 249145, 70, '<td valign="top">Lacks light and white.</td>', 'Lacks light and white.', '2005-10-27 13:19:55.000000', NULL, 1),
(1817918, 249548, 23962, '<td valign="top">Charming.</td>', 'Charming.', '2005-10-27 13:20:10.000000', NULL, 1),
(1817928, 249603, 70, '<td valign="top">I think you could have done without the water drops in this shot. The way they catch the light makes them look like imperfections. Not to mention the fact that it looks totally unnatural on a studio shot. Otherwise, I like the coloring and composition.</td>', 'I think you could have done without the water drops in this shot. The way they catch the light makes them look like imperfections. Not to mention the fact that it looks totally unnatural on a studio shot. Otherwise, I like the coloring and composition.', '2005-10-27 13:22:06.000000', NULL, 1),
(1817932, 248525, 70, '<td valign="top">I think these are kind of creepy! <br/> <br/>While this shot meets the challenge, the composition leaves something to be desired. Placing it somewhere other than dead center would probably create more interest.</td>', 'I think these are kind of creepy!  While this shot meets the challenge, the composition leaves something to be desired. Placing it somewhere other than dead center would probably create more interest.', '2005-10-27 13:24:56.000000', NULL, 1),
(1817936, 247590, 70, '<td valign="top">Very cool perspective!</td>', 'Very cool perspective!', '2005-10-27 13:26:00.000000', NULL, 1),
(1817945, 249581, 43565, '<td valign="top">Good focus.  I like that the shadow completes the feather.</td>', 'Good focus.  I like that the shadow completes the feather.', '2005-10-27 13:28:17.000000', NULL, 1),
(1817948, 249022, 45000, '<td valign="top">Tighter crop would of been better for this picture</td>', 'Tighter crop would of been better for this picture', '2005-10-27 13:29:17.000000', NULL, 1),
(1817950, 249266, 43565, '<td valign="top">To me this does not meet the challenge.</td>', 'To me this does not meet the challenge.', '2005-10-27 13:29:57.000000', NULL, 1),
(1817956, 249551, 43565, '<td valign="top">I really like this.  SImple, very Asian feel.</td>', 'I really like this.  SImple, very Asian feel.', '2005-10-27 13:31:33.000000', NULL, 1),
(1817968, 248219, 3087, '<td valign="top">He''s beautiful! Nice use of the glass for a rough idea of scale. And nicely exposed so as not to blow out the highlights. I like the reflections in the glass and the little catchlight in his eye. Nice shot!</td>', 'He''s beautiful! Nice use of the glass for a rough idea of scale. And nicely exposed so as not to blow out the highlights. I like the reflections in the glass and the little catchlight in his eye. Nice shot!', '2005-10-27 13:36:36.000000', NULL, 1),
(1817970, 249469, 43565, '<td valign="top">Interesting idea, I think it would have been better in this challenge if the back were white instead of black.</td>', 'Interesting idea, I think it would have been better in this challenge if the back were white instead of black.', '2005-10-27 13:37:03.000000', NULL, 1),
(1817974, 249250, 3087, '<td valign="top">I love the image itself - the close crop and the concentration of detail in only one corner of hte frame make a striking composition. But I really don''t like the processing - the posterisation effect and the loss of detail, particularly on the nose - which seems to have been done to make the image fit the challenge rather than because it suits the image better than any other treatment.</td>', 'I love the image itself - the close crop and the concentration of detail in only one corner of hte frame make a striking composition. But I really don''t like the processing - the posterisation effect and the loss of detail, particularly on the nose - which seems to have been done to make the image fit the challenge rather than because it suits the image better than any other treatment.', '2005-10-27 13:39:29.000000', NULL, 1),
(1817978, 247964, 3087, '<td valign="top">Nice balance in terms of retaining detail in the skin and achieving a high-key tonal range but the blow out/ loss of detail along the edge of the towel is a shame. Strong composition and the lack of eye contact works to create an enigmatic mood.</td>', 'Nice balance in terms of retaining detail in the skin and achieving a high-key tonal range but the blow out/ loss of detail along the edge of the towel is a shame. Strong composition and the lack of eye contact works to create an enigmatic mood.', '2005-10-27 13:40:59.000000', NULL, 1),
(1817982, 249377, 3087, '<td valign="top">Beautiful, calming, soft and expertly composed/ exposed. One of my favourites in this challenge.</td>', 'Beautiful, calming, soft and expertly composed/ exposed. One of my favourites in this challenge.', '2005-10-27 13:45:26.000000', NULL, 1),
(1818017, 246951, 32754, '<td valign="top">This is good. composition, light, tonality are great...the lampposts add a lot to this image.</td>', 'This is good. composition, light, tonality are great...the lampposts add a lot to this image.', '2005-10-27 13:57:43.000000', NULL, 1),
(1818021, 246556, 32754, '<td valign="top">I like this a lot; the movement of the eye follows the bridge into the distant background and infinity..good  use of b&amp;w, but it may be sepia, I''m not sure..one of my top picks.</td>', 'I like this a lot; the movement of the eye follows the bridge into the distant background and infinity..good  use of b&w, but it may be sepia, I''m not sure..one of my top picks.', '2005-10-27 13:59:02.000000', NULL, 1),
(1818022, 248006, 32754, '<td valign="top">Visually interesting and arresting..great image.</td>', 'Visually interesting and arresting..great image.', '2005-10-27 13:59:29.000000', NULL, 1),
(1818027, 248107, 32754, '<td valign="top">I love the softness and shadows of the swan''s feathers..lovely and fascinating image...almost has a sculptural quality.</td>', 'I love the softness and shadows of the swan''s feathers..lovely and fascinating image...almost has a sculptural quality.', '2005-10-27 14:00:36.000000', NULL, 1),
(1818034, 249564, 45435, '<td valign="top">awesome</td>', 'awesome', '2005-10-27 14:03:38.000000', NULL, 1),
(1818045, 248525, 36361, '<td valign="top">Funny, I had one of these set for the light on white challenge and ended using it in delicate instead.  Very nice white balance here.</td>', 'Funny, I had one of these set for the light on white challenge and ended using it in delicate instead.  Very nice white balance here.', '2005-10-27 14:07:57.000000', NULL, 1),
(1818052, 248438, 36361, '<td valign="top">Nice capture, you caught her colorful eyes perfectly.</td>', 'Nice capture, you caught her colorful eyes perfectly.', '2005-10-27 14:10:52.000000', NULL, 1),
(1818056, 248997, 36361, '<td valign="top">How in the world did you catch this so perfectly?  Great capture!</td>', 'How in the world did you catch this so perfectly?  Great capture!', '2005-10-27 14:12:14.000000', NULL, 1),
(1818081, 249590, 39664, '<td valign="top">I''m sure you have heard this but how does this fit the challenge?  It is an awesome shot and IMHO, would be more attractive if you crop the bottom 3rd out but I just don''t see light on white.</td>', 'I''m sure you have heard this but how does this fit the challenge?  It is an awesome shot and IMHO, would be more attractive if you crop the bottom 3rd out but I just don''t see light on white.', '2005-10-27 14:22:10.000000', NULL, 1),
(1818083, 247335, 39664, '<td valign="top">This is brilliant color on white.  Nice comp and lovely photo!</td>', 'This is brilliant color on white.  Nice comp and lovely photo!', '2005-10-27 14:22:54.000000', NULL, 1),
(1818085, 249308, 39664, '<td valign="top">I think the black border takes away from this shot.....it "cages" it in too much.  Nice DOF.</td>', 'I think the black border takes away from this shot.....it "cages" it in too much.  Nice DOF.', '2005-10-27 14:23:58.000000', NULL, 1),
(1818087, 249078, 39664, '<td valign="top">Sweet!  This is beautiful and soft and silvery!  Nice work!</td>', 'Sweet!  This is beautiful and soft and silvery!  Nice work!', '2005-10-27 14:24:46.000000', NULL, 1),
(1818090, 249343, 39664, '<td valign="top">Love love love the negative space and the flower is so crisp and clear!  Excellent work!</td>', 'Love love love the negative space and the flower is so crisp and clear!  Excellent work!', '2005-10-27 14:25:43.000000', NULL, 1),
(1818095, 249564, 39664, '<td valign="top">Beautiful!  The only thing I dislike about this photo is the white border....it doesn''t exactly blend with your white background and makes the b/g look like the highlights are too much.</td>', 'Beautiful!  The only thing I dislike about this photo is the white border....it doesn''t exactly blend with your white background and makes the b/g look like the highlights are too much.', '2005-10-27 14:27:22.000000', NULL, 1),
(1818099, 247262, 39664, '<td valign="top">That blue corner really is distracting......comp is good but this needs some help technically.</td>', 'That blue corner really is distracting......comp is good but this needs some help technically.', '2005-10-27 14:28:28.000000', NULL, 1),
(1818102, 246705, 39664, '<td valign="top">AWESOME!  This is soooooo good!  The white cat just blends perfectly with the white background and I love the negative space! 10+</td>', 'AWESOME!  This is soooooo good!  The white cat just blends perfectly with the white background and I love the negative space! 10+', '2005-10-27 14:29:17.000000', NULL, 1),
(1818109, 248949, 44924, '<td valign="top">Great idea. Picture is so sharp, that I have to say it''s both gross and beautiful. Lighting is great and almost to the level of blown detail giving it a great light on white effect.</td>', 'Great idea. Picture is so sharp, that I have to say it''s both gross and beautiful. Lighting is great and almost to the level of blown detail giving it a great light on white effect.', '2005-10-27 14:33:31.000000', NULL, 1),
(1818111, 248997, 44924, '<td valign="top">Awesome action shot. Just a downright awesome picture. If there''s anything I could suggest, which may be just a matter of taste though, it would be to up the shutter speed just slightly to freeze the splashing water even more. Hope to see a ribbon on this one.</td>', 'Awesome action shot. Just a downright awesome picture. If there''s anything I could suggest, which may be just a matter of taste though, it would be to up the shutter speed just slightly to freeze the splashing water even more. Hope to see a ribbon on this one.', '2005-10-27 14:37:18.000000', NULL, 1),
(1818112, 249578, 44924, '<td valign="top">Simple, yet I get drawn to this picture.</td>', 'Simple, yet I get drawn to this picture.', '2005-10-27 14:38:17.000000', NULL, 1),
(1818115, 248976, 28840, '<td valign="top">Really cool photo but I just don''t think the background is white enough. It  looks kinda grey on my computer</td>', 'Really cool photo but I just don''t think the background is white enough. It  looks kinda grey on my computer', '2005-10-27 14:39:00.000000', NULL, 1),
(1818119, 247823, 28840, '<td valign="top">I like the photo but I think the background is a little to dark</td>', 'I like the photo but I think the background is a little to dark', '2005-10-27 14:41:02.000000', NULL, 1),
(1818128, 248148, 44924, '<td valign="top">Great shot, look at that expression on the cat. My vote - 9. As difficult as it is to accomplish with such a white cat, I would have given you a 10 for sure if the cat wasn''t so hard to differentiate from the background. A bright light (or remote flash) behind the cat lighting up the background my have enabled you to turn down the highlights on the cat and still achieve a very white looking background. But look who is talking, I have a similar picture and didn''t think of it until afterwards. Again, just an awesome shot.</td>', 'Great shot, look at that expression on the cat. My vote - 9. As difficult as it is to accomplish with such a white cat, I would have given you a 10 for sure if the cat wasn''t so hard to differentiate from the background. A bright light (or remote flash) behind the cat lighting up the background my have enabled you to turn down the highlights on the cat and still achieve a very white looking background. But look who is talking, I have a similar picture and didn''t think of it until afterwards. Again, just an awesome shot.', '2005-10-27 14:43:12.000000', NULL, 1),
(1818129, 249350, 28840, '<td valign="top">cool photo but the background isn''t really white</td>', 'cool photo but the background isn''t really white', '2005-10-27 14:43:20.000000', NULL, 1),
(1818131, 248854, 44924, '<td valign="top">Very simple and elegant. I love it.</td>', 'Very simple and elegant. I love it.', '2005-10-27 14:44:22.000000', NULL, 1),
(1818132, 248222, 28840, '<td valign="top">The picture looks really dark on my screen</td>', 'The picture looks really dark on my screen', '2005-10-27 14:44:28.000000', NULL, 1),
(1818133, 249430, 43565, '<td valign="top">I think lighting on or behind the petal on the right would have helped.  6 for now, maybe a bump later.</td>', 'I think lighting on or behind the petal on the right would have helped.  6 for now, maybe a bump later.', '2005-10-27 14:45:21.000000', NULL, 1),
(1818135, 249206, 44924, '<td valign="top">Nice idea. This should be the next Apple billboard picture. The highlights on the mouse are blown out against the background, but in my opinion that''s what makes this picture so good.</td>', 'Nice idea. This should be the next Apple billboard picture. The highlights on the mouse are blown out against the background, but in my opinion that''s what makes this picture so good.', '2005-10-27 14:46:05.000000', NULL, 1),
(1818136, 248860, 28840, '<td valign="top">I like it nice composition! First one I''ve seen that is actually light on white</td>', 'I like it nice composition! First one I''ve seen that is actually light on white', '2005-10-27 14:46:19.000000', NULL, 1),
(1818137, 248964, 43565, '<td valign="top">I don''t like the effect of the lighting or post processing on his/her skin.  Pretty blue eyes though.</td>', 'I don''t like the effect of the lighting or post processing on his/her skin.  Pretty blue eyes though.', '2005-10-27 14:46:54.000000', NULL, 1),
(1818138, 247106, 28840, '<td valign="top">The background looks grey not white</td>', 'The background looks grey not white', '2005-10-27 14:46:59.000000', NULL, 1),
(1818140, 247590, 44924, '<td valign="top">Wow, simple and to the point. (get it?  LOL)  Great idea and composition.</td>', 'Wow, simple and to the point. (get it?  LOL)  Great idea and composition.', '2005-10-27 14:47:13.000000', NULL, 1),
(1818142, 246705, 28840, '<td valign="top">It looks a little washed-out on my screen</td>', 'It looks a little washed-out on my screen', '2005-10-27 14:47:47.000000', NULL, 1),
(1818143, 249429, 43565, '<td valign="top">I would like to see a little more of the face on the right.</td>', 'I would like to see a little more of the face on the right.', '2005-10-27 14:48:17.000000', NULL, 1),
(1818147, 249427, 43565, '<td valign="top">The background is not showing up as white on my monitor.</td>', 'The background is not showing up as white on my monitor.', '2005-10-27 14:49:10.000000', NULL, 1),
(1818148, 248964, 28840, '<td valign="top">First off I like the photo but in my opinion I think the flash is a little harsh</td>', 'First off I like the photo but in my opinion I think the flash is a little harsh', '2005-10-27 14:49:16.000000', NULL, 1),
(1818150, 248219, 44924, '<td valign="top">Very nice lighting, no blown details on that bird. Cool shot too.</td>', 'Very nice lighting, no blown details on that bird. Cool shot too.', '2005-10-27 14:49:18.000000', NULL, 1),
(1818152, 249204, 28840, '<td valign="top">On my monitor the background doesn''t look white enough</td>', 'On my monitor the background doesn''t look white enough', '2005-10-27 14:50:22.000000', NULL, 1),
(1818154, 249392, 28840, '<td valign="top">Interesting</td>', 'Interesting', '2005-10-27 14:50:38.000000', NULL, 1),
(1818158, 248943, 44924, '<td valign="top">Very nice picture. Wish I could see a tad more detail in the flower (in the rear) against the background, but still a top 10 picture in my opinion.</td>', 'Very nice picture. Wish I could see a tad more detail in the flower (in the rear) against the background, but still a top 10 picture in my opinion.', '2005-10-27 14:51:48.000000', NULL, 1),
(1818159, 247301, 43565, '<td valign="top">I like this shot, but wish your background was white all the way to the top.  -5-</td>', 'I like this shot, but wish your background was white all the way to the top.  -5-', '2005-10-27 14:51:53.000000', NULL, 1),
(1818161, 247113, 28840, '<td valign="top">In my opinion I think it is to dark to be a light on white photo</td>', 'In my opinion I think it is to dark to be a light on white photo', '2005-10-27 14:52:07.000000', NULL, 1),
