(1818165, 248827, 43565, '<td valign="top">The red is too dark to be a "light" IMO, and the background has tannish yellow in it.  I think the composition would be better if the heart was off center and the beads more in focus.</td>', 'The red is too dark to be a "light" IMO, and the background has tannish yellow in it.  I think the composition would be better if the heart was off center and the beads more in focus.', '2005-10-27 14:53:26.000000', NULL, 1),
(1818166, 249207, 44924, '<td valign="top">What a unique flower, catches my attention immediately. Lighting and composition is great too.</td>', 'What a unique flower, catches my attention immediately. Lighting and composition is great too.', '2005-10-27 14:53:52.000000', NULL, 1),
(1818167, 249206, 28840, '<td valign="top">I like it and it''s not because I am a mac user</td>', 'I like it and it''s not because I am a mac user', '2005-10-27 14:54:33.000000', NULL, 1),
(1818170, 248998, 43565, '<td valign="top">I wish one of the elements had just a tinge of color, otherwise nice shot.</td>', 'I wish one of the elements had just a tinge of color, otherwise nice shot.', '2005-10-27 14:55:14.000000', NULL, 1),
(1818171, 249029, 28840, '<td valign="top">I don''t see light on white</td>', 'I don''t see light on white', '2005-10-27 14:55:25.000000', NULL, 1),
