(1818180, 249247, 43565, '<td valign="top">IMO this is too much color to be "light", and I wish the flowers were not all centered.</td>', 'IMO this is too much color to be "light", and I wish the flowers were not all centered.', '2005-10-27 14:58:33.000000', NULL, 1),
(1818183, 249193, 28840, '<td valign="top">neet composition but I don''t like the sharp shadow under the mug</td>', 'neet composition but I don''t like the sharp shadow under the mug', '2005-10-27 14:59:31.000000', NULL, 1),
(1818184, 247707, 28840, '<td valign="top">really cool</td>', 'really cool', '2005-10-27 14:59:43.000000', NULL, 1),
