INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1820308, 249043, 46489, '<td valign="top">I think your photo meets the challenge and the materials used are simple &amp; effective. I don''t particularly like the subject.</td>', 'I think your photo meets the challenge and the materials used are simple & effective. I don''t particularly like the subject.', '2005-10-28 06:02:41.000000', NULL, 1),
(1820309, 249272, 46679, '<td valign="top">Lovely, both in execution and sense of humor. The flame is difficult, petroleum or lamp oil would have given a more yellow light ... but that''s difficult with a little thingy like this disposeable.</td>', 'Lovely, both in execution and sense of humor. The flame is difficult, petroleum or lamp oil would have given a more yellow light ... but that''s difficult with a little thingy like this disposeable.', '2005-10-28 06:04:13.000000', NULL, 1),
(1820311, 247908, 46679, '<td valign="top">The harness spoils this photo for me.</td>', 'The harness spoils this photo for me.', '2005-10-28 06:06:36.000000', NULL, 1),
(1820312, 249022, 43191, '<td valign="top">OOHHH now this is cool. A pitty about the little bit of ick in the corner of it''s eye. Beautiful photo, very well done.9</td>', 'OOHHH now this is cool. A pitty about the little bit of ick in the corner of it''s eye. Beautiful photo, very well done.9', '2005-10-28 06:07:32.000000', NULL, 1),
