(1820317, 247707, 43191, '<td valign="top">wonderful shot. Good composition, very dramatic. Well done.8</td>', 'wonderful shot. Good composition, very dramatic. Well done.8', '2005-10-28 06:10:06.000000', NULL, 1),
(1820319, 249399, 46679, '<td valign="top">Nice group, but where is the odd pea out?</td>', 'Nice group, but where is the odd pea out?', '2005-10-28 06:11:24.000000', NULL, 1),
