INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1824376, 247190, 25355, '<td valign="top">The challenge called for a white background, not a white frame. Interesting composition, though I''m not really sure what statement you''re trying to make with it.</td>', 'The challenge called for a white background, not a white frame. Interesting composition, though I''m not really sure what statement you''re trying to make with it.', '2005-10-30 06:16:38.000000', NULL, 1),
(1824377, 249043, 25355, '<td valign="top">Perfect for making a copy of The Beatles'' double album (known as, though not officially called, The White Album). ;-) (And as long as you''re making a copy from a source that you actually own yourself).</td>', 'Perfect for making a copy of The Beatles'' double album (known as, though not officially called, The White Album). ;-) (And as long as you''re making a copy from a source that you actually own yourself).', '2005-10-30 06:19:14.000000', NULL, 1),
(1824378, 249610, 25355, '<td valign="top">Highlights must beway blow-out, otherwise we''d be able to see more of the rabbit...</td>', 'Highlights must beway blow-out, otherwise we''d be able to see more of the rabbit...', '2005-10-30 06:23:54.000000', NULL, 1),
(1824379, 249458, 25355, '<td valign="top">Do they really come in a white variety? I''ve never seent hat before.</td>', 'Do they really come in a white variety? I''ve never seent hat before.', '2005-10-30 06:25:11.000000', NULL, 1),
(1824380, 249308, 25355, '<td valign="top">Wow. Baseballs made of china ... surely they''d smash if you hit them with a bat... ;-)</td>', 'Wow. Baseballs made of china ... surely they''d smash if you hit them with a bat... ;-)', '2005-10-30 06:26:51.000000', NULL, 1),
(1824381, 249203, 25355, '<td valign="top">Let me guess ... you must be getting lots of comments along the lines of "You must have been drinking too much beer when you submitted this" or "Aiming for the brown, eh?".</td>', 'Let me guess ... you must be getting lots of comments along the lines of "You must have been drinking too much beer when you submitted this" or "Aiming for the brown, eh?".', '2005-10-30 06:29:13.000000', NULL, 1),
(1824382, 248658, 25355, '<td valign="top">Nice idea, but the photo seems a bit oversharpened.</td>', 'Nice idea, but the photo seems a bit oversharpened.', '2005-10-30 06:30:07.000000', NULL, 1),
(1824383, 248980, 25355, '<td valign="top">Wrong challenge?</td>', 'Wrong challenge?', '2005-10-30 06:32:16.000000', NULL, 1),
(1824384, 249199, 25355, '<td valign="top">Past, it is prime.</td>', 'Past, it is prime.', '2005-10-30 06:32:58.000000', NULL, 1),
(1824465, 248887, 8367, '<td valign="top">Your subject is very pretty. I love her hat and expression. The shadows from the hat on the backdrop  and on her face are somewhat distracting. She should have been placed further from the backdrop and more lighting used on the backdrop. Also, a fill flash for her face. Not every capture has to be perfect, though. I really like this as is.</td>', 'Your subject is very pretty. I love her hat and expression. The shadows from the hat on the backdrop  and on her face are somewhat distracting. She should have been placed further from the backdrop and more lighting used on the backdrop. Also, a fill flash for her face. Not every capture has to be perfect, though. I really like this as is.', '2005-10-30 08:28:52.000000', NULL, 1),
(1824472, 248592, 8367, '<td valign="top">Nice composition. The overall background appears dingy. I think the texture accentuates the dinginess.</td>', 'Nice composition. The overall background appears dingy. I think the texture accentuates the dinginess.', '2005-10-30 08:34:14.000000', NULL, 1),
(1824514, 249326, 8367, '<td valign="top">Nice composition.<br/>The tone is very blue/gray on my monitor.</td>', 'Nice composition.The tone is very blue/gray on my monitor.', '2005-10-30 09:50:56.000000', NULL, 1),
(1824538, 248963, 31005, '<td valign="top">very pretty</td>', 'very pretty', '2005-10-30 10:24:11.000000', NULL, 1),
